import {loadConfirmedRoster} from './roster.js';

import {initialState,standings,forecastIssues,validateWorkspace,simulate,inputKey,profile,scoreMatch,VERSION,actualGames} from './engine.js';
import {importRoster,importSchedule,importScores,importHistory,scoresTemplate,TEMPLATES} from './imports.js';
import {playerStats,allPlay} from './stats.js';
import {cloud} from './cloud.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=2)=>n==null?'—':Number(n).toFixed(d),pct=n=>fmt(n*100,1)+'%';
let state=loadConfirmedRoster(initialState()),revision=null,dirty=false,page='standings',half=0,sort='points-desc',selectedTeam=0,minGames=null,statsSort='average',busy=false,pending=null,worker=null,startupError='';
try{const saved=JSON.parse(localStorage.getItem('monday-workspace')||'null');if(saved){state=validateWorkspace(saved.state);revision=saved.revision??null;dirty=!!saved.dirty;}}catch(e){startupError='Saved local data could not be opened: '+e.message;}
function persist(){try{localStorage.setItem('monday-workspace',JSON.stringify({state,revision,dirty}));}catch{toast('Local storage is full. Download a backup before closing.');}}
function commit(next){pending=null;state=next;dirty=true;persist();render();}
function toast(m){$('#toast').textContent=m;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',7000);}
function download(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
const table=(headers,rows)=>'<div class="table-wrap" tabindex="0"><table><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
const panel=(title,body)=>'<section class="panel"><div class="panel-head"><h2>'+title+'</h2></div><div class="panel-body">'+body+'</div></section>';
const teamName=n=>n===0?'Bye':state.teams.find(t=>t.number===n)?.name||n;
const teamOptions=()=>state.teams.map(t=>'<option value="'+t.number+'" '+(t.number===selectedTeam?'selected':'')+'>'+esc(t.name)+'</option>').join('');
const run=()=>state.runs.find(r=>r.inputKey===inputKey(state));
function render(){
 const tabs=[['standings','Standings'],['forecast','Projections'],['weekly','Team weekly odds'],['stats','Bowler stats'],['allplay','All-Play'],['teams','Teams & bowlers'],['imports','Import results'],['setup','Setup & rules']];
 $('#app').innerHTML='<div class="shell"><aside class="sidebar"><div class="brand">Monday Night<span>CARBONDALE COMMERCIAL</span></div><div class="season-tag">2026–2027 · Valley Bowling Lanes</div><nav>'+tabs.map(([k,n],i)=>'<button class="nav-button '+(page===k?'active':'')+'" data-page="'+k+'"><span class="nav-index">0'+(i+1)+'</span>'+n+'</button>').join('')+'</nav><div class="sidebar-foot">32 weeks · 30 points<strong>85% handicap of 240</strong></div></aside><main class="main"><header class="topbar"><span>'+esc(cloud.email||'Local workspace')+' · '+(dirty?'Unsaved changes':revision?'Loaded revision '+revision:'Not saved online')+'</span><div class="top-actions"><button data-action="backup">Backup</button><button data-action="debug">Debug report</button><button data-action="load" '+(busy?'disabled':'')+'>Load saved league</button><button class="primary" data-action="save" '+(busy?'disabled':'')+'>Save league</button></div></header>'+(startupError?'<div class="notice error">'+esc(startupError)+'</div>':'')+'<div class="page-head"><div class="eyebrow">MONDAY NIGHT LEAGUE</div></div>'+({
 standings:standingsView,forecast:forecastView,weekly:weeklyView,stats:statsView,allplay:allplayView,teams:teamsView,imports:importsView,setup:setupView
 }[page]())+'<footer class="footer"><span>Actual scores and forecasts are calculated separately.</span><span>'+VERSION+'</span></footer></main></div>';
}
const periods=()=>'<div class="tab-pills">'+[0,1,2].map(h=>'<button data-half="'+h+'" class="'+(half===h?'active':'')+'">'+(h?'Half '+h:'Full season')+'</button>').join('')+'</div>';
function standingsView(){
 const rows=standings(state,half);
 return '<div class="page-head"><div><h1>Standings</h1><p>'+state.results.length+' completed weeks · '+state.teams.length+' teams</p></div>'+periods()+'</div>'+(!rows.length?panel('Set up your league','<p>Import the official roster and schedule in Setup. No sample scores or teams have been loaded.</p><button data-page="setup">Open Setup</button>'):panel('League standings',table(['Rank','Team','Division','Points','Scratch team average','Weeks'],rows.map((r,i)=>[i+1,esc(r.name),esc(r.division||'Unassigned'),fmt(r.points,1),fmt(r.average),r.played]))))+panel('Weekly results',table(['Week','Matchup','Points','Unawarded'],state.results.flatMap(r=>r.matches.map(m=>{const s=scoreMatch(m);return [r.week,esc(teamName(m.teamA))+' vs '+esc(teamName(m.teamB)),s.points.join(' – '),s.unawarded];}))));
}
function forecastView(){
 const r=run(),issues=forecastIssues(state),[key,direction]=sort.split('-');
 let rows=r?r.teams.map(t=>({...t,points:half?t.halfPoints[half-1]:t.points})).sort((a,b)=>(direction==='asc'?1:-1)*(a[key]-b[key])):[];
 return '<div class="page-head"><div><h1>Season projections</h1><p>Half points and division-win odds follow the selected half. Playoff and championship odds cover the season.</p></div>'+periods()+'</div>'+panel('Run simulations','<div class="controls"><label>Iterations<input id="iterations" type="number" min="1" max="20000" value="1000"></label><label>Seed<input id="seed" type="number" value="202627"></label><button class="primary" data-action="simulate" '+(busy||issues.length?'disabled':'')+'>'+(busy?'Simulating…':'Run simulations')+'</button><button data-action="cancel" '+(!busy?'disabled':'')+'>Cancel</button></div><progress id="progress" max="1" value="0"></progress>'+(issues.length?'<div class="notice"><strong>Forecast inputs needed</strong><ul>'+issues.map(i=>'<li>'+esc(i)+'</li>').join('')+'</ul></div>':'')+'<p class="fine muted">Forecasts assume the saved five-player lineup stays in the same order, with no absences. Future handicaps update from simulated scoring. Model uncertainty and unresolved-rule assumptions are described in Setup.</p>')+panel('Projected results','<label>Sort<select id="projection-sort">'+[['points-desc','Points ↓'],['points-asc','Points ↑'],['playoffs-desc','Playoff % ↓'],['playoffs-asc','Playoff % ↑'],['champion-desc','Win league % ↓'],['champion-asc','Win league % ↑']].map(([v,l])=>'<option value="'+v+'" '+(sort===v?'selected':'')+'>'+l+'</option>').join('')+'</select></label>'+table(['Team','Projected points',half?'Win division, half '+half:'Win division H1 / H2','Playoffs','Win league'],rows.map(t=>[esc(teamName(t.number)),fmt(t.points,1),half?pct(t.halves[half-1]):t.halves.map(pct).join(' / '),pct(t.playoffs),pct(t.champion)]))+(r?'<p class="fine muted">'+r.iterations+' runs · '+esc(r.createdAt)+'</p>':'<p>No current simulation. Imports and rule changes invalidate prior forecasts.</p>'));
}
function weeklyView(){
 if(!selectedTeam&&state.teams.length)selectedTeam=state.teams[0].number;
 const r=run();
 return '<h1>Team weekly odds</h1>'+panel('Team','<label>Choose team<select id="team-select">'+teamOptions()+'</select></label>')+panel('Weekly matchups',table(['Week','Opponent','Meeting chance','Win / Tie','Expected points','Status'],r?r.weekly.flatMap(w=>{const t=w.teams.find(t=>t.number===selectedTeam);return (t?.opponents||[]).map(o=>[w.week,esc(teamName(o.number)),pct(o.probability),o.number?pct(o.win)+' / '+pct(o.tie):'Bye target',fmt(o.points,1),w.actual?'Actual':'Projected']);}):[]))+panel('Odds history',table(['Saved run','Weeks completed','Playoff %','Win league %'],state.runs.map(r=>{const t=r.teams.find(t=>t.number===selectedTeam);return [esc(r.createdAt),r.completedWeeks,t?pct(t.playoffs):'—',t?pct(t.champion):'—'];})))+'<p class="fine muted">History records forecasts you ran and saved, not reconstructed past predictions.</p>';
}
function statsView(){
 const minimum=minGames??(state.results.length>=3?9:1);
 const rows=state.bowlers.map(b=>playerStats(state,b)).filter(r=>r.games>=minimum).sort((a,b)=>statsSort==='sd'?(a.sd??Infinity)-(b.sd??Infinity):(b[statsSort]??-Infinity)-(a[statsSort]??-Infinity));
 return '<h1>Bowler statistics</h1>'+panel('Current season','<div class="controls"><label>Minimum games<input id="min-games" type="number" min="1" max="96" value="'+minimum+'"></label><label>Rank by<select id="stats-sort">'+[['average','Average'],['improvement','Most improved'],['high','High game'],['highSeries','High series'],['sd','Consistency'],['g200','200+ games'],['g250','250+ games'],['g300','300 games']].map(([k,n])=>'<option value="'+k+'" '+(statsSort===k?'selected':'')+'>'+n+'</option>').join('')+'</select></label></div><p class="fine muted">Only actual imported games count. Blind/vacancy games are excluded. A series requires three actual games that week.</p>')+panel('Leaders',table(['Bowler','Games','Pins','Entering','Average','Improvement','High','Low','High series','Std. dev.','Last 9','200+','250+','300'],rows.map(r=>['<button class="text-button" data-bowler="'+esc(r.id)+'">'+esc(r.name)+'</button>',r.games,r.pins,fmt(r.entering),fmt(r.average),fmt(r.improvement),r.high,r.low,r.highSeries??'—',fmt(r.sd),fmt(r.last9),r.g200,r.g250,r.g300])));
}
function allplayView(){return '<h1>All-Play</h1>'+panel('Handicap series comparison','<p>Each team’s actual handicap series is compared with every other team that week. This is a series-based comparison, not a replay of individual lineup points.</p>'+table(['Team','Wins','Losses','Ties','Win %'],allPlay(state).map(r=>[esc(r.name),r.wins,r.losses,r.ties,pct(r.pct)])));}
function teamsView(){
 return '<h1>Teams & bowlers</h1>'+panel('Entering averages and open positions','<form id="bowler-edit-form" class="controls"><label>Bowler / position<select name="id">'+state.bowlers.map(b=>'<option value="'+esc(b.id)+'">'+esc(b.name)+'</option>').join('')+'</select></label><label>Confirmed name (optional)<input name="name"></label><label>Entering average<input name="entering" type="number" min="0" max="300" required></label><button>Save bowler</button></form><p class="fine">A name is required to fill a vacancy. Missing averages stay blank until verified.</p>')+panel('Edit default lineup and division','<form id="lineup-form" class="controls"><label>Team<select name="team">'+state.teams.map(t=>'<option value="'+t.number+'">'+esc(t.name)+'</option>').join('')+'</select></label><label>Division<input name="division" required></label><label>Five bowler IDs in lineup order<input name="ids" required placeholder="id1,id2,id3,id4,id5"></label><button>Update team</button></form><p class="fine">Changes apply to future forecasts. Imported match lineups remain unchanged. Bowler IDs are listed below.</p>')+state.teams.map(t=>panel(esc(t.name)+' · Division '+esc(t.division||'unassigned'),'<p class="fine">Saved order is the default simulation lineup.</p>'+table(['Slot','Bowler','ID','Entering','Model mean','History games'],t.players.map((id,i)=>{const b=state.bowlers.find(b=>b.id===id),p=profile(state,b);return [i+1,'<button class="text-button" data-bowler="'+esc(id)+'">'+esc(b.name)+'</button>',esc(id),fmt(b.entering),fmt(p.mean),p.priorGames];})))).join('')+panel('Add a floating substitute','<form id="sub-form" class="controls"><label>Unique ID<input name="id" required></label><label>Name<input name="name" required></label><label>Entering average<input name="entering" type="number" min="0" max="300" required></label><button>Add substitute</button></form>')+panel('Substitutes',table(['ID','Name','Entering'],state.bowlers.filter(b=>!state.teams.some(t=>t.players.includes(b.id))).map(b=>[esc(b.id),esc(b.name),b.entering])));
}
function importsView(){
 return '<h1>Import weekly scores</h1>'+panel('Upload a complete week','<div class="controls"><label>Template week<input id="template-week" type="number" min="1" max="32" value="'+Math.min(32,state.results.length+1)+'"></label><button data-action="scores-template">Download template</button></div><p>Keep bowler IDs and lineup positions. Use actual, blind, or vacancy for each game type. Blinds are calculated from the supplied official average; blank average/handicap fields use the app’s calculation.</p><form id="scores-form"><label>CSV file<input name="file" type="file" accept=".csv,text/csv" required></label><div class="controls"><label><input name="replace" type="checkbox">Replace existing week</label><label><input name="officer" type="checkbox">Correction confirmed by a league officer</label><button class="primary">Review import</button></div></form>')+(pending?panel('Review Week '+pending.week,table(['Matchup','Points'],pending.state.results.find(r=>r.week===pending.week).matches.map(m=>[esc(teamName(m.teamA))+' vs '+esc(teamName(m.teamB)),scoreMatch(m).points.join(' – ')]))+'<button class="primary" data-action="apply-import">Apply import</button> <button data-action="discard-import">Cancel</button>'):'');
}
function setupView(){
 return '<h1>Setup & rules</h1>'+panel('League inputs','<p>The attached roster is transcribed: 20 teams, 96 named bowlers, and four vacancies. Listed team numbers and order are preserved; divisions and entering averages are pending. New workspaces start with these teams. Team 0 / slot 0 identifies floating substitutes. Entering averages must follow Rule 6.</p>'+['roster','schedule','history'].map(type=>'<form data-import="'+type+'"><h3>'+type[0].toUpperCase()+type.slice(1)+'</h3><div class="controls"><button type="button" data-template="'+type+'">CSV template</button><label>CSV file<input name="file" type="file" accept=".csv,text/csv" required></label><button>Import '+type+'</button></div></form>').join('<hr>')+'<button data-action="confirmed-roster">Load confirmed roster into empty workspace</button><p class="fine">Schedules use official team numbers. Team B = 0 is a bye. Position rows use kind=position; pair columns may be blank. Regular rows require all teams once per week. Missing position weeks are added automatically.</p>')+panel('Forecast assumptions','<form id="rules-form"><div class="setup-grid"><label>Handicap rounding<select name="rounding"><option value="floor" '+(state.rules.rounding==='floor'?'selected':'')+'>Drop fractional pins (provisional)</option><option value="nearest" '+(state.rules.rounding==='nearest'?'selected':'')+'>Nearest pin</option></select></label><label>Position-round grouping<select name="scope"><option value="division" '+(state.rules.positionScope==='division'?'selected':'')+'>Within divisions (provisional)</option><option value="league" '+(state.rules.positionScope==='league'?'selected':'')+'>Full league</option></select></label></div><div class="stack"><label><input type="checkbox" name="negative" '+(state.rules.negativeHandicap?'checked':'')+'>Allow negative handicap above 240</label><label><input type="checkbox" name="wildcards" '+(state.rules.fillEightWithWildcards?'checked':'')+'>Three divisions: fill all remaining eight-team bracket spots by season points</label><label><input type="checkbox" name="confirmed" '+(state.rules.assumptionsConfirmed?'checked':'')+'>I have reviewed these forecast assumptions</label></div><p class="fine muted">The supplied rules do not specify rounding, position-round grouping/tiebreak order, how three divisions fill eight berths, multi-team roll-offs, or seeding ties. The model uses scratch team average then team number for position ties, randomized knockout roll-offs for tied qualification/seeding, and the same order of starters each week. These forecasts remain provisional. Blank official score fields use these settings.</p><button>Save settings</button></form>')+panel('Adjust a bowler’s projected skill','<form id="adjust-form" class="controls"><label>Bowler<select name="id">'+state.bowlers.map(b=>'<option value="'+esc(b.id)+'">'+esc(b.name)+'</option>').join('')+'</select></label><label>Change in pins<input name="delta" type="number" min="-100" max="100" value="0"></label><label>Start week<input name="start" type="number" min="1" max="35" value="1"></label><label>End week<input name="end" type="number" min="1" max="35" value="32"></label><button>Apply adjustment</button></form>'+table(['Bowler','Pins','Start','End'],Object.entries(state.adjustments).map(([id,a])=>[esc(state.bowlers.find(b=>b.id===id)?.name),a.delta,a.start,a.end])))+panel('Record a completed half roll-off winner','<form id="winner-form" class="controls"><label>Half<select name="half"><option>1</option><option>2</option></select></label><label>Division<input name="division" required></label><label>Winning team number<input name="team" type="number" min="1" required></label><button>Record winner</button></form><p class="fine">Only a team tied for first at the end of that half is accepted. To replace a recorded winner, submit the corrected team number.</p>'+table(['Half / division','Winner'],Object.entries(state.halfWinners).map(([key,n])=>[esc(key),esc(teamName(n))])))+panel('Database & account','<p>Run <a href="./setup/001_monday_workspace.sql" download>001_monday_workspace.sql</a> in your Monday Supabase project. Create an account in Authentication → Users, then add that user to monday_admins using the SQL comment at the end of the script.</p><form id="login-form" class="controls"><label>Email<input name="email" type="email" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button>Sign in</button><button type="button" data-action="logout">Sign out</button></form><p class="fine">Load the saved league after signing in. A save succeeds only when its full contents and revision read back correctly. No passwords or sign-in tokens are included in backups or debug reports.</p>')+panel('Restore a backup','<form id="restore-form"><label>Monday backup JSON<input name="file" type="file" accept=".json" required></label><button>Review backup</button></form>')+panel('Rules implemented',table(['Rule','Behavior'],[['Season','32 weeks; halves end at Weeks 16 and 32'],['Scoring','Five individual points + four team points per game; three series points'],['Blinds','Average minus 10; cannot win individual points; opposing actual score must beat blind + handicap'],['Bye','Scratch targets: team average −50/game, −150/series; individual average −10'],['Average','After nine actual games, floor of actual total pins / games; 21 games official'],['Position rounds','Weeks 10, 13, 16, 26, 29, 32'],['Playoffs','Eight teams; division half winners ahead of wildcards; 1–8 / 2–7 / 3–6 / 4–5; no reseeding'],['Eligibility','Nine games for position rounds except first position round of first half; nine games and no regular role on another team for playoffs']]))+'<p class="fine muted">Imported official scores remain the record. Eligibility issues are reported in the debug file for review; the app does not certify bowlers or make officer rulings.</p>';
}
function showBowler(id){const b=state.bowlers.find(b=>b.id===id),s=playerStats(state,b),d=$('#player-dialog');d.innerHTML='<div class="panel-head"><h2>'+esc(b.name)+'</h2><button id="close-dialog">Close</button></div><div class="panel-body">'+table(['Games','Average','High series','Last 3','Last 6','Last 9'],[[s.games,fmt(s.average),s.highSeries??'—',fmt(s.last3),fmt(s.last6),fmt(s.last9)]])+table(['Week','Team','Actual games','Series / partial total'],s.sessions.map(x=>[x.week,esc(teamName(x.team)),x.scores.join(' / '),x.scores.reduce((a,b)=>a+b,0)]))+'</div>';d.showModal();$('#close-dialog').onclick=()=>d.close();}
function diagnostics(){
 const checks=[];try{validateWorkspace(state);checks.push({name:'Workspace and score structure',pass:true});}catch(e){checks.push({name:'Workspace and score structure',pass:false,detail:e.message});}
 for(const r of state.results)for(const m of r.matches){const s=scoreMatch(m);checks.push({name:'Week '+r.week+' match '+m.teamA+' / '+m.teamB,pass:s.points.every(p=>p>=0&&p<=30)&&s.points[0]+s.points[1]<=30,points:s.points,unawarded:s.unawarded});}
 const warnings=[];
 for(const r of state.results)for(const m of r.matches)for(const team of [m.teamA,m.teamB].filter(Boolean)){
  const players=m.players.filter(p=>p.team===team);
  for(let g=0;g<3;g++){const actual=players.filter(p=>p.types[g]==='actual');if(actual.length<3)warnings.push('Week '+r.week+', team '+team+', game '+(g+1)+': fewer than three actual bowlers.');}
  if([13,16,26,29,32].includes(r.week))for(const p of players.filter(p=>p.types.includes('actual')))if(actualGames(state,p.bowlerId,r.week).length<9)warnings.push('Position-round eligibility: '+p.bowlerId+' had fewer than nine games before Week '+r.week+'.');
 }
 const current=run();if(current)checks.push({name:'Eight playoff berths and one champion',pass:Math.abs(current.teams.reduce((a,t)=>a+t.playoffs,0)-8)<1e-8&&Math.abs(current.teams.reduce((a,t)=>a+t.champion,0)-1)<1e-8});
 return {version:VERSION,createdAt:new Date().toISOString(),state,revision,dirty,cloudVerification:cloud.verification,checks,warnings,forecastIssues:forecastIssues(state),actualSeasonPlayerStats:state.bowlers.map(b=>playerStats(state,b))};
}
async function action(a){
 if(a==='confirmed-roster'){commit(loadConfirmedRoster(state));return;}
 if(busy&&!['cancel','backup','debug'].includes(a))throw Error('Wait for the simulation or cancel it first.');
 if(a==='backup')return download('Monday_League_Backup.json',JSON.stringify({state,revision},null,2),'application/json');
 if(a==='debug')return download('Monday_League_Debug.json',JSON.stringify(diagnostics(),null,2),'application/json');
 if(a==='save'){if(revision===null)throw Error('Sign in and load the saved league first so its revision is known.');const snapshot=structuredClone(state);revision=await cloud.save(snapshot,revision);dirty=inputKey(snapshot)!==inputKey(state)||JSON.stringify(snapshot.runs)!==JSON.stringify(state.runs);persist();render();return toast('Saved and verified by reading back revision '+revision+'.');}
 if(a==='load'){if(dirty&&!confirm('Replace local changes with the saved league? Download a backup first if needed.'))return;const saved=await cloud.load();if(saved){state=saved.state;revision=saved.revision;dirty=false;pending=null;}else {revision=0;toast('No saved workspace yet. Your local league is ready to save.');}persist();render();return;}
 if(a==='logout'){await cloud.logout();revision=null;persist();render();return;}
 if(a==='scores-template')return download('Monday_Week_'+$('#template-week').value+'.csv',scoresTemplate(state,Number($('#template-week').value)),'text/csv');
 if(a==='discard-import'){pending=null;render();return;}
 if(a==='apply-import'){if(!pending)return;const next=pending.state;pending=null;commit(next);return toast('Week imported locally. Save league to persist it online.');}
 if(a==='cancel'){worker?.terminate();worker=null;busy=false;render();return;}
 if(a==='simulate'){
  const iterations=Number($('#iterations').value),seed=Number($('#seed').value);if(!Number.isInteger(iterations)||iterations<1||iterations>20000||!Number.isInteger(seed))throw Error('Choose 1–20,000 iterations and an integer seed.');
  busy=true;render();worker=new Worker('./simulation-worker.js',{type:'module'});
  worker.onmessage=({data})=>{if(data.progress!=null){const p=$('#progress');if(p)p.value=data.progress;return;}worker.terminate();worker=null;busy=false;if(data.error){toast(data.error);render();return;}state.runs=[data.result,...state.runs].slice(0,40);dirty=true;persist();render();toast('Simulation finished. Save league to keep this run.');};
  worker.onerror=e=>{worker?.terminate();worker=null;busy=false;render();toast(e.message||'Simulation worker failed.');};worker.postMessage({state,iterations,seed});
 }
}
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;
 try{
  if(b.dataset.page){page=b.dataset.page;render();return;}
  if(b.dataset.half!=null){half=Number(b.dataset.half);render();return;}
  if(b.dataset.bowler)return showBowler(b.dataset.bowler);
  if(b.dataset.template)return download('Monday_'+b.dataset.template+'_Template.csv',TEMPLATES[b.dataset.template],'text/csv');
  if(b.dataset.action)await action(b.dataset.action);
 }catch(e){toast(e.message);}
});
document.addEventListener('change',e=>{if(e.target.id==='projection-sort'){sort=e.target.value;render();}if(e.target.id==='team-select'){selectedTeam=Number(e.target.value);render();}if(e.target.id==='min-games'){minGames=Math.max(1,Number(e.target.value)||1);render();}if(e.target.id==='stats-sort'){statsSort=e.target.value;render();}});
document.addEventListener('submit',async e=>{
 e.preventDefault();const form=e.target,d=new FormData(form);
 try{
  if(busy)throw Error('Wait for the simulation or cancel it before editing.');
  if(form.dataset.import){const text=await d.get('file').text(),fn={roster:importRoster,schedule:importSchedule,history:importHistory}[form.dataset.import];const next=fn(state,text);pending=null;commit(next);toast('Imported locally. Save league to keep the changes.');}
  else if(form.id==='scores-form'){const text=await d.get('file').text(),next=importScores(state,text,{replace:d.has('replace'),officerConfirmed:d.has('officer')});const changed=next.results.find(r=>JSON.stringify(r)!==JSON.stringify(state.results.find(s=>s.week===r.week)));if(!changed)throw Error('No changed scores.');pending={state:next,week:changed.week};render();}
  else if(form.id==='rules-form'){const next=structuredClone(state);next.rules={rounding:d.get('rounding'),negativeHandicap:d.has('negative'),positionScope:d.get('scope'),fillEightWithWildcards:d.has('wildcards'),assumptionsConfirmed:d.has('confirmed')};commit(next);}
  else if(form.id==='login-form'){await cloud.login(d.get('email'),d.get('password'));revision=null;persist();render();toast('Signed in. Load the saved league before saving.');}
  else if(form.id==='lineup-form'){const next=structuredClone(state),team=next.teams.find(t=>t.number===Number(d.get('team')));if(!team)throw Error('Choose a team.');const ids=d.get('ids').split(',').map(v=>v.trim());team.players=ids;team.division=d.get('division').trim();validateWorkspace(next);commit(next);}
  else if(form.id==='bowler-edit-form'){const next=structuredClone(state),b=next.bowlers.find(b=>b.id===d.get('id')),name=d.get('name').trim(),entering=Number(d.get('entering'));if(!b||!Number.isFinite(entering)||entering<0||entering>300||b.vacancy&&!name)throw Error('Provide a confirmed name for a vacancy and a valid entering average.');if(b.vacancy){b.id='bowler-'+b.id+'-'+Date.now();for(const t of next.teams)t.players=t.players.map(id=>id===d.get('id')?b.id:id);}if(name)b.name=name;b.vacancy=false;b.entering=entering;commit(next);}
  else if(form.id==='sub-form'){const id=d.get('id').trim(),name=d.get('name').trim(),entering=Number(d.get('entering'));if(!id||!name||state.bowlers.some(b=>b.id===id)||!Number.isFinite(entering)||entering<0||entering>300)throw Error('Use a unique ID, name, and valid entering average.');const next=structuredClone(state);next.bowlers.push({id,name,entering,team:0,history:[]});commit(next);}
  else if(form.id==='adjust-form'){const id=d.get('id'),delta=Number(d.get('delta')),start=Number(d.get('start')),end=Number(d.get('end'));if(!state.bowlers.some(b=>b.id===id)||end<start||start<1||end>35||!Number.isFinite(delta)||Math.abs(delta)>100)throw Error('Invalid skill adjustment.');const next=structuredClone(state);if(delta===0)delete next.adjustments[id];else next.adjustments[id]={delta,start,end};commit(next);}
  else if(form.id==='winner-form'){const half=Number(d.get('half')),division=d.get('division'),team=Number(d.get('team')),rows=standings(state,half).filter(r=>r.division===division);if(!state.results.some(r=>r.week===half*16)||!rows.some(r=>r.number===team&&r.points===rows[0]?.points))throw Error('Winner must be tied for first in that division after the half ends.');const next=structuredClone(state);next.halfWinners[half+':'+division]=team;commit(next);}
  else if(form.id==='restore-form'){const data=JSON.parse(await d.get('file').text()),next=validateWorkspace(data.state||data);if(!confirm('Restore '+next.teams.length+' teams and '+next.results.length+' weeks? This replaces local data.'))return;pending=null;commit(next);}
 }catch(e){toast(e.message);}
});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
render();
